<?php
require_once __DIR__.'/config.php'; require_once __DIR__.'/includes/policy-system.php'; requireLogin();
$db=db();hrPolicyEnsureSchema($db);$u=currentUser();$v=hrPolicyVersion($db,(int)($_GET['id']??0));$isAdmin=$u['role']!=='employee';$preview=$isAdmin&&($_GET['preview']??'')==='employee';$eid=hrPolicyEmployeeId($u);
if(!$v||(!$isAdmin&&!in_array($v['status'],array('published','superseded'),true))){http_response_code(404);exit('Policy not found.');}
if(empty($v['digital_html'])){http_response_code(409);exit('This policy version does not yet have a verified digital document.');}
$ack=null;$legal='';
if($preview){$legal='Preview Employee';}
elseif(!$isAdmin){
    $legal=hrPolicyLegalName($db,$eid);
    $s=$db->prepare("INSERT INTO hr_policy_acknowledgements (policy_id,version_id,employee_id,user_id,opened_at,last_opened_at) VALUES (?,?,?,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE opened_at=COALESCE(opened_at,NOW()),last_opened_at=NOW()");
    $s->execute(array($v['policy_id'],$v['id'],$eid,$u['id']));
    $s=$db->prepare("SELECT * FROM hr_policy_acknowledgements WHERE version_id=? AND employee_id=?");$s->execute(array($v['id'],$eid));$ack=$s->fetch(PDO::FETCH_ASSOC);
    if(empty($ack['last_opened_at'])||strtotime($ack['last_opened_at'])<time()-300)hrPolicyAudit($db,'policy_opened',$v['policy_id'],$v['id'],$eid);
}
$toc=array();if(preg_match_all('/<h2 id="([^"]+)">(.*?)<\/h2>/s',$v['digital_html'],$matches,PREG_SET_ORDER))foreach($matches as $m)$toc[]=array('id'=>$m[1],'text'=>html_entity_decode(strip_tags($m[2]),ENT_QUOTES,'UTF-8'));
$signed=$ack&&!empty($ack['signed_at']);$readPercent=$ack?(float)$ack['reading_percent']:0;$employeeExperience=!$isAdmin||$preview;
$displayHtml=$v['digital_html'];if($employeeExperience)$displayHtml=preg_replace('/<h2[^>]*>\s*Portal acknowledgement record\s*<\/h2>.*$/is','',$displayHtml);
?>
