<header class="digital-policy-header"><span class="eyebrow">Company policy</span><h1><?=htmlspecialchars($v['title'])?></h1><div class="viewer-meta"><span>Version <b><?=htmlspecialchars($v['version_number'])?></b></span><span>Created <b><?=date('j F Y',strtotime($v['created_date']))?></b></span><span>Effective <b><?=date('j F Y',strtotime($v['effective_date']))?></b></span><span>Next review <b><?=htmlspecialchars($v['next_review']?:'Not scheduled')?></b></span></div><p class="status-pill"><?=htmlspecialchars(hrPolicyDisplayStatus($v))?></p><?php if($isAdmin&&!$preview):?><a class="secondary-btn preview-employee-btn" href="policy-view.php?id=<?=$v['id']?>&amp;preview=employee">Preview Employee Experience</a><?php endif;?><?php if($signed):?><div class="signed-policy-notice"><b>Signed &amp; Acknowledged</b><span><?=date('j M Y H:i',strtotime($ack['signed_at']))?></span><a href="policy-receipt.php?id=<?=$ack['id']?>">View acknowledgement</a><button type="button" onclick="window.print()">Print policy</button></div><?php endif;?></header>
<?php if($isAdmin&&!$preview):?><section class="document-panel compact"><div><h2>Original approved document</h2><p>The source file is preserved unchanged and linked to this digital version.</p><p class="hash">Document SHA-256 <?=htmlspecialchars($v['document_hash'])?><br>Digital SHA-256 <?=htmlspecialchars($v['digital_hash'])?></p></div><a class="secondary-btn" target="_blank" href="policy-file.php?id=<?=$v['id']?>">Open original</a></section><?php endif;?>
<div class="digital-policy-layout"><details class="policy-toc" aria-label="Policy contents" open><summary>Contents</summary><nav><?php foreach($toc as $item):?><a href="#<?=htmlspecialchars($item['id'])?>"><?=htmlspecialchars($item['text'])?></a><?php endforeach;?></nav></details><article class="policy-digital-content" id="policyDocument"><?=$displayHtml?></article></div>
