<?php if($signed):?><div class="signed-state"><h3>SIGNED &amp; ACKNOWLEDGED</h3><p>Signed by <?=htmlspecialchars($ack['legal_name'])?> on <?=date('j M Y H:i',strtotime($ack['signed_at']))?>.</p><a class="primary-btn" href="policy-receipt.php?id=<?=$ack['id']?>">View Acknowledgement</a></div>
<?php else:?><div class="signature-gate" id="signatureGate">Continue reading to the acknowledgement section to enable signing.</div><form method="post" action="policy-action.php" id="signatureForm" aria-disabled="true"><input type="hidden" name="csrf" value="<?=htmlspecialchars(hrPolicyCsrf())?>"><input type="hidden" name="action" value="sign"><input type="hidden" name="ajax" value="1"><input type="hidden" name="version_id" value="<?=$v['id']?>"><input type="hidden" name="signature_method" id="signatureMethod" value="drawn"><input type="hidden" name="signature_data" id="signatureData"><fieldset id="signatureFields" disabled><label class="check"><input type="checkbox" name="ack_confirm" required> I confirm that I have read and understood this policy.</label><label>Full Legal Name *<input name="legal_name" required value="<?=htmlspecialchars($legal)?>"></label><div class="signature-tabs"><button type="button" class="active" data-method="drawn">Draw signature</button><button type="button" data-method="typed">Typed fallback</button></div><div data-pane="drawn"><canvas id="signaturePad" width="720" height="220"></canvas><button type="button" class="secondary-btn" id="clearSignature">Clear Signature</button></div><div data-pane="typed" hidden><p>By typing my full legal name below and selecting Sign &amp; Acknowledge, I intend this electronic action to serve as my signature and acknowledgement of this policy.</p><label>Typed signature *<input name="typed_signature" value=""></label></div><button class="primary-btn" id="signButton" type="submit">Sign &amp; Acknowledge</button></fieldset></form><div class="notice error" id="signatureError" hidden></div><?php endif;?></section><?php endif;?></main>
<?php if($employeeExperience&&!$signed):?><dialog id="exitWarning" class="exit-warning"><h2>POLICY ACKNOWLEDGEMENT NOT COMPLETED</h2><p>You have not yet completed your acknowledgement of:</p><p><b><?=htmlspecialchars($v['title'])?><br>Version <?=htmlspecialchars($v['version_number'])?></b></p><p>Acknowledgement is mandatory and must be completed by: <b><?=date('j F Y',strtotime($v['acknowledgement_deadline']))?></b></p><div><button class="primary-btn" type="button" data-continue-reading>Continue Reading</button><a class="secondary-btn" href="policies.php" data-leave-policy>Leave for Now</a></div></dialog><script>window.hrPolicy={csrf:<?=json_encode(hrPolicyCsrf())?>,versionId:<?=$v['id']?>,readingPercent:<?=$readPercent?>,readingPosition:<?=($ack?(int)$ack['reading_position']:0)?>,signed:false,preview:<?=$preview?'true':'false'?>};</script><script src="includes/policy-signature.js?v=20260811-preview"></script><?php endif;?>
